    72|class ProviderBoundary extends Component<ProviderBoundaryProps, ProviderBoundaryState> {
    73|  constructor(props: ProviderBoundaryProps) {
    74|    super(props);
    75|    this.state = { hasError: false, error: null, traceId: null };
    76|  }
    77|  static getDerivedStateFromError(error: Error): Partial<ProviderBoundaryState> {
    78|    return {
    79|      hasError: true,
    80|      error,
    81|      traceId: 'IVX-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 8),
    82|    };
    83|  }
    84|  componentDidCatch(error: Error) {
    85|    const category = classifyProviderError(error);
    86|    console.warn(`[IVX] Provider "${this.props.name}" crashed — category: ${category}`, error.message, error.stack);
    87|  }
    88|  render() {
    89|    if (this.state.hasError) {
    90|      const category = this.state.error ? classifyProviderError(this.state.error) : 'UNKNOWN_ERROR';
    91|      return (
    92|        <View style={styles.providerError}>
    93|          <Text style={styles.providerErrorName}>IVX encountered a rendering error</Text>
    94|          <Text style={styles.providerErrorMsg}>
    95|            {category}: {this.state.error?.message || "Unknown error"}
    96|          </Text>
    97|          {this.state.traceId && (
    98|            <Text style={styles.providerErrorTrace}>Trace ID: {this.state.traceId}</Text>
