   238|export async function pollVideoStatus(videoId: string, maxAttempts = 30): Promise<UploadStage> {
   239|  for (let i = 0; i < maxAttempts; i++) {
   240|    try {
   241|      const res = await fetch(`${API_BASE}/api/ivx/video-platform/admin/videos/${videoId}`);
   242|      if (res.ok) {
   243|        const data = await res.json() as { status?: string; playback_status?: string };
   244|        const status = (data.playback_status || data.status || '').toLowerCase();
   245|        if (status === 'ready' || status === 'published') return 'ready';
   246|        if (status === 'failed') return 'failed';
   247|      }
   248|    } catch {
   249|      // Continue polling
   250|    }
   251|    await new Promise(r => setTimeout(r, 3000));
