     2| * SafeVideo — defensive wrapper around expo-av Video for Android stability.
     3| *
     4| * expo-av on Android is prone to native crashes when:
     5| *   - posterSource/usePoster is enabled with remote URIs
     6| *   - HLS (.m3u8) sources are fed to the legacy player
     7| *   - multiple Video instances mount at once inside a FlatList
     8| *   - shouldPlay flips before the player is ready
     9| *
    10| * This component disables poster on Android, falls back from HLS to MP4, and
    11| * surfaces load errors so the app survives bad videos instead of crashing.
    12| * Poster is rendered as a separate Image layer (not expo-av posterSource).
    13| */
    14|import React, { useEffect, useRef, useState } from 'react';
    15|import { View, Text, ActivityIndicator, Platform, StyleSheet, TouchableOpacity } from 'react-native';
    16|import { Video, ResizeMode, type VideoReadyForDisplayEvent } from 'expo-av';
    17|import { RefreshCw } from 'lucide-react-native';
    18|import Colors from '@/constants/colors';
    19|
    20|interface SafeVideoProps {
    21|  uri: string | null | undefined;
    22|  posterUri?: string | null | undefined;
    23|  style?: any;
    24|  shouldPlay?: boolean;
    25|  isMuted?: boolean;
    26|  isLooping?: boolean;
    27|  resizeMode?: ResizeMode;
    28|  onProgress?: (progress: number) => void;
    29|  onPlaybackStatusUpdate?: (status: { isPlaying: boolean; durationMillis: number; positionMillis: number }) => void;
    30|  testID?: string;
    31|}
    32|
    33|const GOLD = Colors.primary;
    34|const MAX_RETRIES = 2;
    35|
    36|function pickPlaybackUri(input: string | null | undefined): string | null {
    37|  if (!input) return null;
    38|  // On Android, prefer progressive MP4 over HLS to avoid expo-av native crashes.
    39|  // But if HLS is the ONLY option, still return it rather than null (null causes
    40|  // infinite loading and potential resource leaks from repeated mount cycles).
    41|  if (Platform.OS === 'android' && input.toLowerCase().endsWith('.m3u8')) {
    42|    // Return the HLS URI as a last resort — ExoPlayer can handle basic HLS
    43|    return input;
    44|  }
    45|  return input;
    46|}
    47|
    48|export default function SafeVideo({
    49|  uri,
    50|  posterUri,
    51|  style,
    52|  shouldPlay = false,
    53|  isMuted = true,
    54|  isLooping = true,
    55|  resizeMode = ResizeMode.COVER,
