    61|  const [error, setError] = useState<string | null>(null);
    62|  const [loading, setLoading] = useState<boolean>(true);
    63|  const [ready, setReady] = useState<boolean>(false);
    64|  const [retryCount, setRetryCount] = useState<number>(0);
    65|  const playbackUri = pickPlaybackUri(uri);
    66|
