    68|  useEffect(() => {
    69|    setError(null);
    70|    setLoading(true);
    71|    setReady(false);
    72|    setRetryCount(0);
    73|  }, [playbackUri]);
    74|
    75|  // CRITICAL: Unload the native ExoPlayer when unmounting.
    76|  // The ref is read in the cleanup closure, but we must use a ref object
    77|  // (not a captured snapshot) so we get the LIVE player instance at
    78|  // cleanup time — not the null value that existed at mount time.
    79|  // Previous bug: `const player = videoRef.current` captured null at
    80|  // mount, so unloadAsync was never called → native players leaked on
    81|  // every reel swipe → memory grew → OOM crash after ~15-25 transitions.
    82|  useEffect(() => {
    83|    return () => {
    84|      try {
    85|        const player = videoRef.current;
    86|        if (player) {
    87|          void player.stopAsync().catch(() => {});
    88|          void player.unloadAsync().catch(() => {});
    89|        }
    90|      } catch {
    91|        // ignore — player may already be gone
    92|      }
    93|    };
    94|  }, []);
    95|
    96|  // Also unload when the URI changes (before the new source loads)
    97|  useEffect(() => {
    98|    return () => {
    99|      try {
   100|        const player = videoRef.current;
   101|        if (player) {
   102|          void player.unloadAsync().catch(() => {});
   103|        }
   104|      } catch {}
   105|    };
   106|  }, [playbackUri]);
   107|
   108|  const handleRetry = () => {
   109|    if (retryCount >= MAX_RETRIES) return;
   110|    setRetryCount((c) => c + 1);
   111|    setError(null);
   112|    setLoading(true);
   113|    setReady(false);
   114|  };
   115|
   116|  if (!playbackUri) {
   117|    return (
   118|      <View style={[styles.container, style]} testID={testID ? `${testID}-no-source` : undefined}>
   119|        {posterUri ? (
   120|          <View style={[styles.container, style]}>
   121|            <View style={[StyleSheet.absoluteFill, { backgroundColor: '#111' }]} />
   122|            <ActivityIndicator size="large" color={GOLD} style={StyleSheet.absoluteFill} />
   123|          </View>
   124|        ) : (
   125|          <ActivityIndicator size="large" color={GOLD} />
   126|        )}
   127|      </View>
   128|    );
   129|  }
   130|
