   132|  // The poster is rendered by the parent component (ReelVideoPlayer) as an Image.
   133|  const showPoster = Platform.OS !== 'android' && !!posterUri;
   134|  const posterSource = showPoster ? { uri: posterUri as string } : undefined;
   135|  const usePoster = showPoster;
   136|
   137|  return (
   138|    <View style={[styles.container, style]} testID={testID}>
   139|      <Video
   140|        ref={videoRef}
   141|        source={{ uri: playbackUri }}
   142|        style={StyleSheet.absoluteFill}
   143|        resizeMode={resizeMode}
   144|        shouldPlay={shouldPlay && ready}
   145|        isLooping={isLooping}
   146|        isMuted={isMuted}
   147|        useNativeControls={false}
   148|        usePoster={usePoster}
   149|        posterSource={posterSource}
   150|        onLoadStart={() => setLoading(true)}
   151|        onReadyForDisplay={(e: VideoReadyForDisplayEvent) => {
   152|          setLoading(false);
   153|          setReady(true);
   154|        }}
   155|        onLoad={(status) => {
   156|          setLoading(false);
   157|          if (status.isLoaded) {
   158|            setReady(true);
   159|          }
   160|        }}
   161|        onError={(err) => {
   162|          setLoading(false);
   163|          setReady(false);
   164|          setError(typeof err === 'string' ? err : 'Video failed to load');
   165|          if (__DEV__) {
   166|            console.warn('[SafeVideo] load error:', err);
   167|          }
   168|        }}
   169|        onPlaybackStatusUpdate={(status) => {
   170|          if (status.isLoaded && status.durationMillis && status.durationMillis > 0) {
