   172|            onPlaybackStatusUpdate?.({
   173|              isPlaying: status.isPlaying ?? false,
   174|              durationMillis: status.durationMillis,
   175|              positionMillis: status.positionMillis ?? 0,
   176|            });
   177|          }
   178|        }}
   179|      />
   180|      {loading && !error && (
   181|        <View style={styles.overlay} pointerEvents="none">
   182|          <ActivityIndicator size="large" color={GOLD} />
   183|        </View>
   184|      )}
   185|      {error && (
   186|        <View style={styles.overlay} pointerEvents="auto">
   187|          {retryCount < MAX_RETRIES ? (
   188|            <TouchableOpacity style={styles.retryBtn} onPress={handleRetry} activeOpacity={0.8}>
   189|              <RefreshCw size={16} color="#000" />
   190|              <Text style={styles.retryText}>Retry</Text>
   191|            </TouchableOpacity>
   192|          ) : (
   193|            <ActivityIndicator size="small" color="rgba(255,255,255,0.6)" />
   194|          )}
   195|        </View>
   196|      )}
   197|    </View>
   198|  );
   199|}
   200|
   201|const styles = StyleSheet.create({
   202|  container: {
   203|    flex: 1,
   204|    backgroundColor: '#000',
   205|    alignItems: 'center',
   206|    justifyContent: 'center',
   207|  },
   208|  overlay: {
   209|    ...StyleSheet.absoluteFillObject,
