    99|function getCachedEntry(key: string): CacheEntry | null {
   100|  const entry = FEED_CACHE.get(key);
   101|  if (!entry) return null;
   102|  if (Date.now() > entry.expiresAt) {
   103|    FEED_CACHE.delete(key);
