   109|function setCachedEntry(key: string, body: string, status: number): void {
   110|  if (FEED_CACHE.size >= FEED_CACHE_MAX) {
   111|    const oldest = [...FEED_CACHE.entries()].sort((a, b) => a[1].expiresAt - b[1].expiresAt)[0];
   112|    if (oldest) FEED_CACHE.delete(oldest[0]);
