   129|async function withFeedCache(key: string, handler: () => Promise<Response>): Promise<Response> {
   130|  const cached = getCachedEntry(key);
   131|  if (cached) return cachedJson(cached.body, cached.status);
   132|
   133|  const inflight = FEED_CACHE_LOCKS.get(key);
   134|  if (inflight) {
