    88|### Managing Giphy's
    89|
    90|```js
    91|import * as FileSystem from 'expo-file-system/legacy';
    92|
    93|const gifDir = FileSystem.cacheDirectory + 'giphy/';
    94|const gifFileUri = (gifId: string) => gifDir + `gif_${gifId}_200.gif`;
    95|const gifUrl = (gifId: string) => `https://media1.giphy.com/media/${gifId}/200.gif`;
    96|
    97|// Checks if gif directory exists. If not, creates it
    98|async function ensureDirExists() {
    99|  const dirInfo = await FileSystem.getInfoAsync(gifDir);
   100|  if (!dirInfo.exists) {
   101|    console.log("Gif directory doesn't exist, creating…");
   102|    await FileSystem.makeDirectoryAsync(gifDir, { intermediates: true });
   103|  }
   104|}
   105|
   106|// Downloads all gifs specified as array of IDs
   107|export async function addMultipleGifs(gifIds: string[]) {
   108|  try {
   109|    await ensureDirExists();
   110|
   111|    console.log('Downloading', gifIds.length, 'gif files…');
   112|    await Promise.all(gifIds.map(id => FileSystem.downloadAsync(gifUrl(id), gifFileUri(id))));
   113|  } catch (e) {
   114|    console.error("Couldn't download gif files:", e);
   115|  }
   116|}
   117|
   118|// Returns URI to our local gif file
   119|// If our gif doesn't exist locally, it downloads it
   120|export async function getSingleGif(gifId: string) {
   121|  await ensureDirExists();
   122|
   123|  const fileUri = gifFileUri(gifId);
