     9|/**
    10| * The single process-local Reel player. It deliberately never creates one player
    11| * per feed item: moving the active reel swaps the media item on this instance.
    12| */
    13|class ReelPlaybackCoordinator(context: Context) {
    14|    val player: ExoPlayer = ExoPlayer.Builder(context.applicationContext).build().apply {
    15|        repeatMode = Player.REPEAT_MODE_ONE
    16|        playWhenReady = false
    17|        addListener(object : Player.Listener {
    18|            override fun onPlayerError(error: androidx.media3.common.PlaybackException) {
    19|                activeReelId?.let { MediaDiagnostics.playbackFailed(it, error) }
    20|            }
    21|        })
    22|    }
    23|
    24|    var activeReelId: String? = null
    25|        private set
    26|
    27|    fun activate(reel: IVXReel, mayPlay: Boolean) {
    28|        val source = reel.playbackUrl ?: run {
    29|            pause()
    30|            return
    31|        }
    32|        if (activeReelId != reel.id || player.currentMediaItem?.localConfiguration?.uri.toString() != source) {
    33|            player.stop()
    34|            player.clearMediaItems()
    35|            player.setMediaItem(MediaItem.Builder().setMediaId(reel.id).setUri(source).build())
    36|            player.prepare()
    37|            activeReelId = reel.id
    38|        }
    39|        player.playWhenReady = mayPlay && reel.status in setOf("ready", "published", "")
    40|        MediaDiagnostics.playing(if (player.playWhenReady) reel.id else null)
    41|    }
    42|
    43|    fun pause() {
    44|        player.playWhenReady = false
    45|        player.pause()
    46|        MediaDiagnostics.stopped()
    47|    }
    48|
    49|    fun release() {
    50|        activeReelId = null
    51|        MediaDiagnostics.stopped()
    52|        player.release()
    53|    }
